/* Connected local design walkthrough. Uses sample media; no network or device writes. */
const basePhone=phone,baseRender=render,baseGo=go,baseSheet=sheet,baseChat=chat;
let journeyStarted=false,pickerSelection=new Set(),pickerKind='Photos',pickerFilter='All',pickerReturn='select',pickerSearch='',importing=false,importedIds=new Set(),importTimer,jobTimer,exportTimer,jobPhase='idle',jobStage=0,exportPhase='idle',sentPrompt='',promptHistory=[],planDraft='',photosAllowed=false,savedCount=0,shareSaved=false,bundleName='Summer moments',lastReturn='review';
const nativeStatus=()=>`<div class="status"><span>9:41</span><div class="island"></div><span class="statusicons">${ic('signal')}${ic('wifi')}${ic('battery')}</span></div>`;
const counts=(ids=[...chosen])=>({photos:ids.filter(i=>!media[i].video).length,videos:ids.filter(i=>!!media[i].video).length});
const countCopy=(ids=[...chosen])=>{const c=counts(ids);return [c.photos?c.photos+' '+(c.photos===1?'photo':'photos'):'',c.videos?c.videos+' '+(c.videos===1?'video':'videos'):''].filter(Boolean).join(' · ')};
const minSlides=()=>profile==='Instagram'?2:1;
function journeyHeader(title='New post',back){return nativeStatus()+`<header class="apphead">${back?ib('back','Back',back):ib('menu','Open projects','drawer')}<span class="title">${title}</span>${ib('more','Post options','options')}</header>`}
function chatComposer(place='Tell Kria what you want…',kind='creation',disabled=false){const val=kind==='refine'?planDraft:note,can=kind==='refine'?!!val.trim()&&!importing:chosen.size>=minSlides()&&!importing;return `<form class="creation-composer" data-kind="${kind}">${btn('','journey:add','plus','composer-attach','aria-label="Add photos and videos" '+(disabled?'disabled':''))}<textarea id="${kind==='refine'?'plan-message':'creation-message'}" aria-label="${kind==='refine'?'Refine the direction':'Message Kria'}" rows="${Math.min(4,Math.max(1,Math.ceil(val.length/28)))}" placeholder="${place}">${esc(val)}</textarea>${btn('','journey:send','send','composer-send',`aria-label="${kind==='refine'?'Send direction change':val.trim()?'Send media and prompt':'Send media'}" ${!can||disabled?'disabled':''}`)}</form>`}
function formatView(){return journeyHeader('New chat')+body(`<div class="format-intro"><span class="format-kria">kria</span><h2>What are we making?</h2><p class="sub">Choose a starting point.<br>We’ll shape the details together.</p></div><div class="format-track" aria-label="Choose a format"><button class="format-choice" disabled><img class="format-poster" src="../../../../src/apps/web/public/plan/type-posters/montage.jpg" alt="Montage example"><h3>Montage</h3><p>Moments, cut to the music.</p></button><button class="format-choice" disabled><img class="format-poster" src="../../../../src/apps/web/public/plan/type-posters/voiceover.jpg" alt="Narrated example"><h3>Narrated</h3><p>Your story, with a voice.</p></button><button class="format-choice" disabled><img class="format-poster" src="../../../../src/apps/web/public/plan/type-posters/talking.jpg" alt="Talking example"><h3>Talking</h3><p>Keep your voice at the center.</p></button><div class="format-choice post-choice"><button class="post-select" data-do="journey:choose"><div class="format-art swipe-art" role="img" aria-label="A swipeable series of photos and videos"><div class="cover-track" aria-hidden="true"><div class="cover-slide"><img src="../../../../src/apps/web/public/landing/raw-story/corfu.jpg" alt=""><span class="cover-count">1 / 3</span></div><div class="cover-slide"><video src="../../../../src/apps/web/public/landing/raw-story/alberobello.mp4" poster="../../../../src/apps/web/public/landing/raw-story/alberobello.jpg" muted playsinline loop preload="none" tabindex="-1"></video><span class="cover-kind">${ic('play')}Video</span><span class="cover-count">2 / 3</span></div><div class="cover-slide"><img src="../../../../src/apps/web/public/landing/raw-story/trulli-street.jpg" alt=""><span class="cover-count">3 / 3</span></div><div class="cover-slide"><img src="../../../../src/apps/web/public/landing/raw-story/corfu.jpg" alt=""><span class="cover-count">1 / 3</span></div></div><div class="cover-shade" aria-hidden="true"></div><div class="cover-pages" aria-hidden="true"><span></span><span></span><span></span></div></div><h3>Photo & video<br>post</h3><p>One story. Made to swipe.</p></button><button class="cover-toggle" data-do="cover:toggle" aria-label="Pause format preview" aria-pressed="false"><span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 6v12M16 6v12"/></svg></span></button></div></div><p class="format-hint">Swipe to explore formats ${ic('next')}</p>`)+`<footer class="appfoot creation-foot">${chatComposer('Tell Kria what you want…','creation',true)}</footer>`}
function selectedMedia(){return `<div class="attached-grid">${[...chosen].map(i=>`<div class="attached-tile">${img(i)}${btn('','journey:remove:'+i,'close','remove-media',`aria-label="Remove ${media[i].name}" ${importing?'disabled':''}`)}<span class="media-kind">${media[i].video?ic('play')+media[i].video:'Photo'}</span>${importing&&!importedIds.has(i)?'<span class="import-status"><span class="spinner"></span>Adding…</span>':''}</div>`).join('')}</div>`}
select=function(){const ready=chosen.size>0;return journeyHeader('Photo & video post','journey:format')+body(`<div class="meta" style="margin-top:0"><span class="chip">${ic('layers')}Slide post</span>${btn(profile,'platform','down')}</div><h2>${ready?'These are your moments.':'Start with your moments.'}</h2><p class="sub" style="margin-top:10px">${ready?'Tell me the story you want to share.':'Add photos, videos, or a little of both. I’ll help you find the story.'}</p>${ready?selectedMedia():btn(`<span class="add-circle">${ic('plus')}</span><strong>Add photos & videos</strong><span>Choose from Photos or Files</span>`,'journey:add','','empty-media')}<div class="media-receipt"><span>${ready?(importing?'Adding '+chosen.size+' moments…':countCopy()):profile==='Instagram'?'2–20 moments · Portrait 4:5':'1–35 photos · Portrait 9:16'}</span>${ready?btn('Add more','journey:add','plus'):''}</div>${ready?`<div class="prompt-invite" ${note.trim()?'hidden':''}><span class="assistant-label">Kria</span><p>What should this post feel like?</p><div class="prompt-chips">${btn('A slow summer diary','journey:prompt:slow','','suggestion')}${btn('Bright and playful','journey:prompt:bright','','suggestion')}</div></div>`:'<div class="empty-explanation"><span class="assistant-label">Kria</span><p>I’ll suggest an order, a cover, and a caption. You’ll have the final say.</p></div>'}`)+`<footer class="appfoot creation-foot">${chosen.size===1&&profile==='Instagram'?'<p class="small">Add one more moment for an Instagram post.</p>':''}${chatComposer(importing?'Add instructions while these arrive…':ready?'Add instructions (optional)':'Tell Kria the story…')}</footer>`};
function sourceSheet(){return `<div class="shade"><section class="sheet source-sheet" role="dialog" aria-modal="true" aria-label="Add photos and videos"><div class="grab"></div><div class="sheethead"><h3>Add your moments</h3>${ib('close','Close media sources','dismiss')}</div>${btn(`<span class="source-icon">${ic('grid')}</span><span><strong>Photo Library</strong><small>Photos and videos from your iPhone</small></span>${ic('next')}`,'journey:source:Photos','','source-row')}${btn(`<span class="source-icon">${ic('layers')}</span><span><strong>Choose Files</strong><small>Browse files and folders</small></span>${ic('next')}`,'journey:source:Files','','source-row')}</section></div>`}
function pickerView(){const ids=media.map((m,i)=>i).filter(i=>(pickerFilter==='All'||(pickerFilter==='Photos'?!media[i].video:!!media[i].video))&&(!pickerSearch||media[i].name.toLowerCase().includes(pickerSearch.toLowerCase())));return nativeStatus()+`<section class="native-picker" aria-label="${pickerKind==='Photos'?'Photo Library':'Files picker'}"><header class="picker-head">${btn('Cancel','journey:cancelpicker','','system-action')}<strong>${pickerKind==='Photos'?'Photos':'Files'}</strong>${btn('Add'+(pickerSelection.size?' ('+pickerSelection.size+')':''),'journey:addselected','','system-action',pickerSelection.size?'':'disabled')}</header><div class="picker-toolbar"><label class="picker-search">${ic('grid')}<input id="picker-search" placeholder="Search your moments" aria-label="Search sample media" value="${esc(pickerSearch)}"></label><div class="picker-tabs">${['All','Photos','Videos'].map(f=>btn(f,'journey:filter:'+f,'',pickerFilter===f?'active':'',`aria-pressed="${pickerFilter===f}"`)).join('')}</div><div class="picker-section"><h3>${pickerKind==='Photos'?'Recent days':'On My iPhone'}</h3><span>${ids.length} items</span></div></div><div class="picker-scroll ${pickerKind==='Files'?'files-list':'photo-grid'}">${ids.map(i=>pickerKind==='Files'?btn(`${img(i)}<span class="file-description"><strong>${media[i].name}.${media[i].video?'mov':'jpg'}</strong><small>${media[i].video?'Video · '+media[i].video:'Photo · JPEG'}</small></span><span class="picker-tick ${pickerSelection.has(i)?'on':''}">${pickerSelection.has(i)?ic('check'):''}</span>`,'journey:pick:'+i,'','file-row',`aria-pressed="${pickerSelection.has(i)}" ${profile==='TikTok'&&media[i].video?'disabled':''}`):btn(`${img(i)}<span class="picker-tick ${pickerSelection.has(i)?'on':''}">${pickerSelection.has(i)?[...pickerSelection].indexOf(i)+1:''}</span>${media[i].video?`<span class="duration">${ic('play')}${media[i].video}</span>`:''}`,'journey:pick:'+i,'','photo-choice',`aria-label="${pickerSelection.has(i)?'Deselect':'Select'} ${media[i].name}" aria-pressed="${pickerSelection.has(i)}" ${profile==='TikTok'&&media[i].video?'disabled':''}`)).join('')}${!ids.length?'<p class="sub" style="padding:20px">No matching moments.</p>':''}</div><footer class="picker-footer"><span>${pickerSelection.size?pickerSelection.size+' selected':'Select the moments for your post'}</span>${btn(pickerSelection.size===media.length?'Deselect all':'Select all','journey:pickall','','system-action')}</footer></section>`}
function mediaSummary(){return `<div class="conversation-media"><div class="tiny-stack">${[...chosen].slice(0,3).map(img).join('')}</div><div><strong>${chosen.size} moments attached</strong><span>${countCopy()}</span></div></div>`}
function planView(pending=false){const ids=[...chosen],first=ids[0]??0,last=ids.at(-1)??5;return journeyHeader('Summer moments','journey:media')+body(`<div class="conversation-choice">${ic('layers')}Photo & video post · ${profile}</div>${mediaSummary()}${sentPrompt?`<div class="user-bubble creation-bubble">${esc(sentPrompt)}</div>`:''}<div class="plan-assistant"><span class="assistant-label">Kria</span>${pending?`<div class="plan-thinking"><span class="spinner"></span><p>Finding the thread in your moments…</p></div>`:`<h2>Here’s how I’d shape it.</h2><p class="sub">${/bright|playful|lively|energetic/i.test(sentPrompt)?'A bright opening, little surprises, and a moment that makes you smile.':'A quiet opening, little discoveries, and a moment to linger on.'}</p><div class="story-outline"><div>${img(first)}<span><small>OPEN</small><strong>${media[first].name}</strong></span></div>${ids.length>2?`<div>${img(ids[1])}<span><small>EXPLORE</small><strong>${ids.length-2} moments, connected</strong></span></div>`:''}${ids.length>1?`<div>${img(last)}<span><small>CLOSE</small><strong>${media[last].name}</strong></span></div>`:''}</div><div class="plan-facts"><div><span>Feel</span><strong>${/bright|playful|lively|energetic/i.test(sentPrompt)?'Bright & playful':'Warm & unhurried'}</strong></div><div><span>Text</span><strong>Short, thoughtful lines</strong></div><div><span>Post</span><strong>${chosen.size} slides · ${profile==='Instagram'?'4:5':'9:16'}</strong></div></div>`}</div>`,'plan-body')+`<footer class="appfoot creation-foot plan-foot">${pending?'':btn(importing?'Adding moments…':'Create post','journey:create','','primary',importing?'disabled':'')}${chatComposer(pending?'Add a thought…':'Anything you’d like to change?','refine',pending)}</footer>`}
function createProgress(){return journeyHeader('Summer moments')+body(`<div class="loadingart">${img(order[1]??order[0])}${img(order.at(-1))}${img(order[0])}</div><h2>Your moments.<br>Coming together.</h2><p class="sub" style="margin-top:12px">${chosen.size} moments, shaped into one post.</p><div class="statusline" role="status"><span class="spinner"></span><div>${['Finding the strongest opening…','Connecting your moments…','Finishing your draft…'][jobStage]}<p class="small">Your media and direction are saved.</p></div></div><p class="small">You can leave this screen. Your draft will be here when you return.</p>`)+foot('Back to chat','chat')}
chat=function(){if(!journeyStarted)return baseChat();return journeyHeader('Summer moments')+body(`<div class="conversation-choice">${ic('layers')}Photo & video post · ${profile}</div>${mediaSummary()}${sentPrompt?`<div class="user-bubble creation-bubble">${esc(sentPrompt)}</div>`:''}<span class="assistant-label">Kria</span>${jobPhase==='working'?`<h2 style="margin-top:12px">Your post is taking shape.</h2><div class="statusline"><span class="spinner"></span><span>${['Finding the opening…','Connecting your moments…','Finishing your draft…'][jobStage]}</span></div>`:jobPhase==='ready'?`<h2 style="margin-top:12px">Your first draft is ready.</h2><p class="sub" style="margin:12px 0 18px">Swipe through it. Change anything. I’m right there if you need a hand.</p><div class="chat-result">${canvas(cover)}<div><strong>Summer moments</strong><span>${order.length} slides · ${profile}</span>${btn('Open post','review','next')}</div></div>`:'<h2 style="margin-top:12px">Ready when you are.</h2><p class="sub" style="margin-top:12px">Add your moments and tell me what you have in mind.</p>'}`)+foot(jobPhase==='working'?'View progress':jobPhase==='ready'?'Open post':'Continue creating',jobPhase==='working'?'journey:progress':jobPhase==='ready'?'review':'journey:media')};
function savedView(){return journeyHeader('Summer moments','export')+body(`<div class="saved-hero"><span class="success-ring">${ic('check')}</span><h2>${shareSaved?'Your post is in Files.':'Your post is in Photos.'}</h2><p class="sub">${order.length} slides, saved and ready.</p>${shareSaved?`<p class="small" style="margin-top:10px">${esc(bundleName)} · On My iPhone</p>`:''}</div><div class="saved-strip">${order.slice(0,4).map(img).join('')}</div><div class="saved-next"><h3>One last thing.</h3><p>Open ${profile} and select your slides in order. Paste the caption when you’re ready.</p></div><div class="captionblock"><div class="fieldlabel">Post caption ${btn('Copy','copy','copy')}</div><p>${esc(caption)}</p></div>`)+foot('Done','gallery')}
function savingView(){return journeyHeader('Saving slides')+body(`<div class="saved-hero"><span class="spinner large-spinner"></span><h2>Saving your moments.</h2><p class="sub" role="status">${savedCount} of ${order.length} slides saved</p></div><div class="strip">${order.map(img).join('')}</div><p class="sub" style="margin-top:22px">Keep Kria open while your slides are added.</p>`)}
function permissionSheet(){return `<div class="shade permission-shade"><section class="system-alert" role="dialog" aria-modal="true" aria-label="Photos permission"><div class="app-avatar">k</div><h3>Allow “Kria” to add to your photos?</h3><p>Save the photos and videos from your finished post to your library.</p>${btn('Allow Add Only','journey:allowphotos','','alert-action')}${btn('Don’t Allow','journey:denyphotos','','alert-action')}</section></div>`}
function shareSheet(){return `<div class="shade"><section class="sheet share-sheet" role="dialog" aria-modal="true" aria-label="Share slide files"><div class="grab"></div><div class="sheethead"><div><h3>Summer moments</h3><p class="small">${order.length} slide files + caption.txt</p></div>${ib('close','Close share sheet','dismiss')}</div><div class="share-file-preview">${order.slice(0,4).map(img).join('')}</div><div class="share-apps">${['AirDrop','Messages','More'].map((n,i)=>btn(`<span>${ic(i===0?'share':i===1?'caption':'more')}</span>${n}`,'journey:shareinfo','','share-app')).join('')}</div>${btn('Save to Files','journey:savefiles','layers','share-action')}${btn('Share as ZIP','journey:savefiles','download','share-action')}<p class="small" style="margin-top:15px">Choose the slides in order when you post.</p></section></div>`}
function filesSaveSheet(){return `<div class="shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="Save to Files"><div class="sheethead">${btn('Cancel','share','','system-action')}<h3>Save to Files</h3>${btn('Save','journey:filesdone','','system-action')}</div><div class="files-folder">${ic('layers')}On My iPhone ${ic('next')}</div><label class="fieldlabel" for="bundle-name">Name</label><input id="bundle-name" value="${esc(bundleName)}"><p class="sub" style="margin-top:18px">${order.length} ordered slides and caption.txt</p></section></div>`}
function startPicker(kind){pickerKind=kind;pickerSelection=new Set(chosen);pickerFilter='All';pickerSearch='';pickerReturn=['arrange','review','plan'].includes(screen)?screen:'select';baseGo('picker')}
function beginImport(){chosen=new Set(pickerSelection);importedIds=new Set();importing=true;go(pickerReturn);let ids=[...chosen],index=0;clearInterval(importTimer);importTimer=setInterval(()=>{if(index<ids.length)importedIds.add(ids[index++]);if(index>=ids.length){clearInterval(importTimer);importing=false;if(pickerReturn==='arrange'||pickerReturn==='review'){order=[...chosen];if(!order.includes(cover))cover=order[0];if(!order.includes(current))current=order[0];}}if(['select','prompt','arrange','review','plan'].includes(screen))render();},250)}
function sendCreation(){if(screen==='plan'||screen==='planning'){if(!planDraft.trim()||importing)return;promptHistory.push(planDraft.trim());sentPrompt=promptHistory.join('\n\n');planDraft=''}else{if(importing||chosen.size<minSlides())return;sentPrompt=note.trim()||'Find the story in these moments.';promptHistory.push(sentPrompt)}go('planning');clearTimeout(jobTimer);jobTimer=setTimeout(()=>{if(screen==='planning')go('plan')},1300)}
function createDraft(){if(importing||chosen.size<minSlides())return;order=[...chosen];current=order[0];cover=current;jobPhase='working';jobStage=0;const bright=/bright|playful|lively|energetic/i.test(sentPrompt);media[current].text=bright?'Good days.\nGreat company.':'A slower\nkind of\nsummer.';media[current].position='top';caption=bright?'Good company, little adventures, and all the moments in between.':'Little streets, long afternoons, and nowhere else to be. A few summer moments worth keeping.';go('composing');clearInterval(jobTimer);jobTimer=setInterval(()=>{jobStage++;if(jobStage>=3){clearInterval(jobTimer);jobStage=2;jobPhase='ready';if(screen==='composing')go('review');else render()}else render()},1000)}
function saveSlides(){savedCount=0;shareSaved=false;go('saving');clearInterval(exportTimer);exportTimer=setInterval(()=>{savedCount++;if(savedCount>=order.length){clearInterval(exportTimer);go('saved')}else render()},220)}
const originalReviewA=reviewA;reviewA=function(){return originalReviewA().replace('data-do="review" aria-label="Back to post"','data-do="chat" aria-label="Back to chat"')};
const journeyViews={format:formatView,picker:pickerView,prompt:select,planning:()=>planView(true),plan:()=>planView(false),saved:savedView,saving:savingView};
phone=function(s){if(s==='composing'&&journeyStarted)return `<div class="phone">${createProgress()}<div class="homebar"></div></div>`;if(journeyViews[s])return `<div class="phone">${journeyViews[s]()}<div class="homebar"></div>${modal?sheet():''}${toast?`<div class="toast" role="status">${esc(toast)}</div>`:''}</div>`;return basePhone(s)};
sheet=function(){if(modal==='add')return sourceSheet();if(modal==='photos-permission')return permissionSheet();if(modal==='share')return shareSheet();if(modal==='save-files')return filesSaveSheet();if(modal==='photos-denied')return `<div class="shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="Photos access not allowed"><div class="grab"></div><div class="sheethead"><h3>Your post is still ready.</h3>${ib('close','Close','dismiss')}</div><p class="sub">You can save the files instead, or allow Photos access in Settings.</p>${btn('Save to Files','journey:savefiles','layers','primary')}${btn('Not now','dismiss','','secondary')}</section></div>`;return baseSheet()};
go=function(s){if(s==='kria-demo'){if(!chosen.size)chosen=new Set([0,1,2,3,4,5]);baseGo('review');modal='kria';render();return}if(['prompt','plan','planning','composing','review','arrange','export','saved','recovery'].includes(s)&&!chosen.size&&!journeyStarted)chosen=new Set([0,1,2,3,4,5]);baseGo(s)};
steps.splice(0,steps.length,['format','Choose format'],['select','Add your moments'],['picker','Photo Library'],['prompt','Prompt Kria'],['plan','Review direction'],['composing','Create the post'],['review','Review & edit'],['kria-demo','Edit with Kria'],['export','Export'],['saved','Saved'],['gallery','Gallery']);
Object.assign(desc,{format:['Start in the existing chat','Choose Photo & video post from the familiar format carousel. The other formats remain where creators expect them.'],select:['Photos and videos, together','Start empty. Add from Photos or Files, see every attachment, and remove or add more before sending. The existing chat composer carries the prompt.'],picker:['The familiar iOS picker','Pick several photos and videos, then confirm the selection. This is a local visual stand-in for the system picker, using sample media.'],prompt:['Say what you have in mind','Try a suggested direction or type your own. Send the selected moments and prompt together. The typed text stays when you add or remove media.'],plan:['A direction you can agree on','Kria shows the proposed story before creating it. Refine the direction in chat or tap Create post.'],planning:['Keep the conversation visible','Your chosen media and exact prompt stay in view while Kria shapes the direction.'],composing:['Make waiting feel safe','Show a truthful stage. Leaving for chat does not cancel creation; the ready post returns to the same conversation.'],saved:['Finish with a useful receipt','Confirm how many separate slides were saved and keep the caption within reach. A denied Photos permission offers Files instead.'],saving:['Show actual save progress','In the app, each completed file advances the count. These timers are simulated for the walkthrough.']});
const journeyBaseRender=baseRender;
render=function(){const focused=document.activeElement?.id,cursor=document.activeElement?.selectionStart;if(q.get('board')==='journey'){renderJourneyBoard();return}journeyBaseRender();document.querySelector('.prompt-invite')?.toggleAttribute('hidden',!!note.trim());const aside=document.querySelector('.aside>div');if(aside){aside.innerHTML=`<div class="overline">The full experience</div><h3>Option A, from the start.</h3><p>Choose the format → add moments → prompt Kria → agree on a direction → review and edit → save.</p>${btn('Start the walkthrough','journey:restart','next','asidelink')}<p style="margin-top:12px">Use the sample library to try the flow. AI replies, imports, and saves are simulated locally.</p>`}document.querySelectorAll('.steps button').forEach(b=>{if(screen==='prompt'&&b.dataset.do==='nav:select')b.classList.remove('active')});if(focused&&['creation-message','plan-message','picker-search'].includes(focused)){const field=document.getElementById(focused);if(field){field.focus();if(cursor!=null)field.setSelectionRange(cursor,cursor)}}else if(modal)setTimeout(()=>document.querySelector('.sheet button:not([disabled]),.system-alert button')?.focus(),0)};
function seedStage(s){if(s==='format'){journeyStarted=false;chosen.clear();note='';return}journeyStarted=true;if(s==='select'){chosen.clear();note='';return}chosen=new Set([0,1,2,3,4,5]);order=[...chosen];current=0;cover=0;note='Make a warm, unhurried summer diary. Keep the text short and let the little moments tell the story.';sentPrompt=note;if(s==='picker'){chosen.clear();pickerSelection=new Set([0,1,2,3,4,5]);pickerKind='Photos'}if(s==='review'||s==='export'||s==='saved')jobPhase='ready'}
function renderJourneyBoard(){const wanted=q.get('part')||'start';const spec=wanted==='finish'?[['composing','07 / Create your post'],['review','08 / Review and edit'],['kria-demo','09 / Ask Kria for a change'],['export','10 / Prepare the slide files'],['saved','11 / Save to Photos'],['gallery','12 / Find it in Gallery']]:[['format','01 / Choose the format'],['select','02 / Start with your moments'],['picker','03 / Pick photos and videos'],['prompt','04 / Tell Kria the story'],['planning','05 / Send your direction'],['plan','06 / Review the approach']];const cards=spec.map(([s,label])=>{seedStage(s);screen=s;modal='';if(s==='kria-demo'){screen='review';modal='kria';kriaRequest='Shorten the opening text';kriaProposal={type:'text',target:0,text:'Summer, slowly.'}}const markup=phone(s==='kria-demo'?'review':s);modal='';return `<section class="boardphone"><div class="label">${label}</div>${markup}</section>`});root.innerHTML=`<main class="board journey-board"><header class="boardhead"><div><div class="overline">Kria / KRI-160 / The complete mobile experience</div><h1>${wanted==='finish'?'From the first draft to your next post.':'From an idea to a story worth swiping.'}</h1></div><p>Option A · Native chat flow<br>Photos + videos + your direction.</p></header><div class="boardphones">${cards.join('')}</div><div class="boardfoot"><span>Selected design direction · Floating Kria AI retained</span><span>Local prototype · Sample media and conversations</span></div></main>`}
function journeyAction(a){const parts=a.split(':'),op=parts[1],v=parts.slice(2).join(':');switch(op){case'choose':journeyStarted=true;chosen.clear();order=[0,1,2,3,4,5];jobPhase='idle';go('select');break;case'restart':clearInterval(jobTimer);clearInterval(importTimer);clearInterval(exportTimer);journeyStarted=false;chosen.clear();note='';sentPrompt='';promptHistory=[];jobPhase='idle';importing=false;photosAllowed=false;go('format');break;case'format':go('format');break;case'media':go('select');break;case'add':modal='add';render();break;case'source':startPicker(v);break;case'cancelpicker':go(pickerReturn);break;case'pick':if(profile==='TikTok'&&media[+v].video)break;pickerSelection.has(+v)?pickerSelection.delete(+v):pickerSelection.add(+v);render();break;case'pickall':{const allowed=media.map((m,i)=>i).filter(i=>profile!=='TikTok'||!media[i].video);pickerSelection=pickerSelection.size===allowed.length?new Set():new Set(allowed);render();break}case'filter':pickerFilter=v;render();break;case'addselected':if(pickerSelection.size)beginImport();break;case'remove':chosen.delete(+v);render();break;case'prompt':note=v==='bright'?'Make this bright and playful. Use short, fun text and connect the little surprises.':'Make a warm, unhurried summer diary. Keep the text short and let the little moments tell the story.';render();document.getElementById('creation-message')?.focus();break;case'send':sendCreation();break;case'create':createDraft();break;case'progress':go('composing');break;case'allowphotos':photosAllowed=true;saveSlides();break;case'denyphotos':modal='photos-denied';render();break;case'savefiles':modal='save-files';render();break;case'filesdone':shareSaved=true;go('saved');break;case'shareinfo':say('This local walkthrough opens no external apps. Save to Files demonstrates the completed export.');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-do]');if(!el||q.get('board'))return;const a=el.dataset.do;if(a.startsWith('journey:')){e.preventDefault();e.stopImmediatePropagation();journeyAction(a);return}if(a.startsWith('nav:')){e.stopImmediatePropagation();const dest=a.slice(4);if(['format','select','picker','prompt','plan','planning','composing','saved'].includes(dest)){seedStage(dest)}go(dest);return}if(a==='sampleadd'){e.stopImmediatePropagation();startPicker('Photos');return}if(a==='add'){e.stopImmediatePropagation();modal='add';render();return}if(a==='play'){e.stopImmediatePropagation();const video=document.createElement('video');video.src='../../../../src/apps/web/public/landing/raw-story/'+(current===2?'alberobello':'istanbul')+'.mp4';video.poster='../../../../src/apps/web/public/landing/raw-story/'+media[current].img;video.controls=true;video.autoplay=true;video.playsInline=true;const stage=document.querySelector('.previewwrap .canvas');if(stage){stage.querySelector('img').replaceWith(video);stage.querySelector('.playbutton')?.remove();video.play().catch(()=>{})}return}if(a==='savephotos'){e.stopImmediatePropagation();if(photosAllowed)saveSlides();else{modal='photos-permission';render()}return}if(a==='select'&&(screen==='gallery'||modal==='drawer')){e.stopImmediatePropagation();journeyAction('journey:restart');return}if(a==='compose'){e.stopImmediatePropagation();sendCreation();return}if(a==='platform:TikTok'&&journeyStarted){e.stopImmediatePropagation();if([...chosen].some(i=>media[i].video)){modal='incompatible';render()}else{profile='TikTok';modal='';render()}return}if(a==='photodraft'&&journeyStarted){e.stopImmediatePropagation();profile='TikTok';chosen=new Set([...chosen].filter(i=>!media[i].video));order=[...chosen];if(order.length){current=cover=order[0]}go('select');return}},true);
document.addEventListener('input',e=>{if(e.target.id==='bundle-name')bundleName=e.target.value;if(e.target.id==='creation-message'){note=e.target.value;document.querySelector('.prompt-invite')?.toggleAttribute('hidden',!!note.trim());e.target.style.height='auto';e.target.style.height=Math.min(116,e.target.scrollHeight)+'px';const send=document.querySelector('.composer-send');if(send)send.disabled=chosen.size<minSlides()||importing||screen==='format'}if(e.target.id==='plan-message'){planDraft=e.target.value;const send=document.querySelector('.composer-send');if(send)send.disabled=!planDraft.trim()||screen==='planning'}if(e.target.id==='picker-search'){pickerSearch=e.target.value;const pos=e.target.selectionStart;render();const f=document.getElementById('picker-search');f.focus();f.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.matches('.creation-composer')){e.preventDefault();sendCreation()}});
document.addEventListener('keydown',e=>{if(modal==='photos-permission'&&e.key==='Tab'){const buttons=[...document.querySelectorAll('.system-alert button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus()}}if(['creation-message','plan-message'].includes(e.target.id)&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(screen!=='format')sendCreation()}if(e.key==='Escape'&&screen==='picker'){e.preventDefault();go(pickerReturn)}});
if(!q.has('screen')&&!q.has('board')){screen='format';chosen.clear()}else if(['format','select','picker','prompt','plan','planning','composing','saved'].includes(screen)){seedStage(screen)}render();
